--
-- Name: match_products(public.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_products(query_embedding public.vector, match_threshold double precision, match_count integer) RETURNS TABLE(id integer, name character varying, price numeric, unit character varying, description text, image_url text, category_id integer, stock integer, low_stock_threshold integer, similarity double precision)
    LANGUAGE plpgsql
    AS $$
  BEGIN
    RETURN QUERY
    SELECT
      p.id,
      p.name,
      p.price,
      p.unit,
      p.description,
      p.image_url,
      p.category_id,
      p.stock,
      p.low_stock_threshold,
      1 - (p.embedding <=> query_embedding) AS similarity
    FROM products p
    WHERE p.embedding IS NOT NULL 
      AND 1 - (p.embedding <=> query_embedding) > match_threshold
    ORDER BY p.embedding <=> query_embedding
    LIMIT match_count;
  END;
  $$;


