-- Name: nancy_allergy_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_allergy_view AS
 SELECT ar.allergy_id,
    ar.allergy_name,
    ar.excluded_item,
    ar.action_type,
    ar.substitution_guidance,
    ar.safety_note,
    i.ingredient_id,
    i.ingredient_name,
    i.requires_hard_filter
   FROM (public.allergy_rules ar
     LEFT JOIN public.ingredients i ON ((lower(ar.excluded_item) = lower(i.ingredient_name))));


--
-- Name: unit_conversions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_conversions (
    id integer NOT NULL,
    ingredient_id text,
    ingredient_name text,
    recipe_quantity_type text,
    selling_unit text,
    base_unit_factor numeric,
    rounding_rule text,
    display_rule text
);


--
-- Name: nancy_cart_builder_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_cart_builder_view AS
 SELECT mi.meal_id,
    mi.meal_name,
    mi.ingredient_id,
    mi.ingredient_name,
    mi.qty_per_person,
    mi.recipe_unit,
    mi.requirement_type,
    mi.importance_score,
    mi.budget_adjustment_rule,
    uc.selling_unit,
    uc.base_unit_factor,
    uc.rounding_rule,
    uc.display_rule,
    c.sku,
    c.product_name,
    c.unit_price,
    c.availability_status,
    c.sales_channel,
    i.allergen_tag,
    i.requires_hard_filter
   FROM (((public.meal_ingredients mi
     LEFT JOIN public.unit_conversions uc ON ((mi.ingredient_id = uc.ingredient_id)))
     LEFT JOIN public.catalogue c ON (((mi.ingredient_id = c.ingredient_id) AND (c.eligible_for_ai = true))))
     LEFT JOIN public.ingredients i ON ((mi.ingredient_id = i.ingredient_id)));


