--
-- Name: nancy_daily_insights; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_daily_insights AS
 SELECT (created_at)::date AS date,
    journey_type,
    count(*) AS conversations,
    count(*) FILTER (WHERE (cart_confirmed = true)) AS cart_confirmations,
    round((((count(*) FILTER (WHERE (cart_confirmed = true)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS conversion_rate_pct
   FROM public.nancy_conversations
  GROUP BY ((created_at)::date), journey_type
  ORDER BY ((created_at)::date) DESC, (count(*)) DESC;


--
-- Name: nancy_journey_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_journey_summary AS
 SELECT journey_type,
    count(*) AS total_conversations,
    count(*) FILTER (WHERE (cart_confirmed = true)) AS cart_conversions,
    round((((count(*) FILTER (WHERE (cart_confirmed = true)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS conversion_pct,
    min(created_at) AS first_seen,
    max(created_at) AS last_seen
   FROM public.nancy_conversations
  GROUP BY journey_type
  ORDER BY (count(*)) DESC;


--
-- Name: nancy_meal_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_meal_view AS
 SELECT m.meal_id,
    m.meal_name,
    m.meal_category,
    m.cuisine_origin,
    m.regional_context,
    m.default_serving_size,
    m.complexity,
    m.supports_budget_mode,
    m.best_for,
    m.meal_time,
    mi.ingredient_id,
    mi.ingredient_name,
    mi.requirement_type,
    mi.qty_per_person,
    mi.recipe_unit,
    mi.role_in_meal,
    mi.importance_score,
    mi.budget_adjustment_rule,
    i.allergen_tag,
    i.requires_hard_filter,
    i.dietary_tag
   FROM ((public.meals m
     JOIN public.meal_ingredients mi ON ((m.meal_id = mi.meal_id)))
     LEFT JOIN public.ingredients i ON ((mi.ingredient_id = i.ingredient_id)));


--
-- Name: nancy_product_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_product_view AS
 SELECT c.sku,
    c.product_name,
    c.ingredient_id,
    c.linked_ingredient,
    c.product_category,
    c.selling_unit,
    c.unit_price,
    c.currency,
    c.availability_status,
    c.location,
    c.sales_channel,
    c.eligible_for_ai,
    c.product_allergen_tag,
    i.ingredient_category,
    i.allergen_tag AS ingredient_allergen_tag,
    i.dietary_tag,
    i.requires_hard_filter,
    COALESCE(inv.available_qty, (0)::bigint) AS stock_qty,
    inv.inventory_status,
    inv.movement_class
   FROM ((public.catalogue c
     LEFT JOIN public.ingredients i ON ((c.ingredient_id = i.ingredient_id)))
     LEFT JOIN ( SELECT inventory.sku,
            sum(inventory.available_qty) AS available_qty,
            max(inventory.inventory_status) AS inventory_status,
            max(inventory.movement_class) AS movement_class
           FROM public.inventory
          GROUP BY inventory.sku) inv ON ((c.sku = inv.sku)))
  WHERE (c.eligible_for_ai = true);


--
-- Name: substitutions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.substitutions (
    substitution_id text NOT NULL,
    original_ingredient_id text,
    original_ingredient text,
    substitute_ingredient_id text,
    substitute_ingredient text,
    substitution_reason text,
    taste_impact text,
    estimated_price_impact numeric,
    safety_status text,
    ai_action text
);


--
-- Name: nancy_substitution_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_substitution_view AS
 SELECT s.substitution_id,
    s.original_ingredient_id,
    s.original_ingredient,
    s.substitute_ingredient_id,
    s.substitute_ingredient,
    s.substitution_reason,
    s.taste_impact,
    s.estimated_price_impact,
    s.safety_status,
    s.ai_action,
    c.unit_price AS substitute_price,
    c.availability_status AS substitute_availability,
    c.sku AS substitute_sku
   FROM (public.substitutions s
     LEFT JOIN public.catalogue c ON (((s.substitute_ingredient_id = c.ingredient_id) AND (c.eligible_for_ai = true))));


--
-- Name: product_associations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_associations (
    id integer NOT NULL,
    product_a text NOT NULL,
    product_b text NOT NULL,
    association_strength integer DEFAULT 1,
    association_type text DEFAULT 'meal_co_occurrence'::text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: nancy_top_associations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nancy_top_associations AS
 SELECT pa.product_a,
    pa.product_b,
    pa.association_strength,
    c1.unit_price AS price_a,
    c2.unit_price AS price_b,
    c1.availability_status AS stock_a,
    c2.availability_status AS stock_b
   FROM ((public.product_associations pa
     LEFT JOIN public.catalogue c1 ON (((c1.product_name ~~* (('%'::text || pa.product_a) || '%'::text)) AND (c1.eligible_for_ai = true))))
     LEFT JOIN public.catalogue c2 ON (((c2.product_name ~~* (('%'::text || pa.product_b) || '%'::text)) AND (c2.eligible_for_ai = true))))
  ORDER BY pa.association_strength DESC
 LIMIT 100;


